namespace lycan { namespace {
bool isSha256(const std::string&s){if(s.size()!=64)return false;return std::all_of(s.begin(),s.end(),[](unsigned char c){return std::isxdigit(c)!=0;});}
std::string lower(std::string s){std::transform(s.begin(),s.end(),s.begin(),[](unsigned char c){return static_cast<char>(std::tolower(c));});return s;}
std::string field(const std::string&o,const std::string&key){auto n="\""+key+"\"";auto k=o.find(n);if(k==std::string::npos)return{};auto c=o.find(':',k+n.size());if(c==std::string::npos)return{};auto q=o.find('"',c+1);if(q==std::string::npos)return{};std::string v;bool esc=false;for(size_t i=q+1;i<o.size();++i){char x=o[i];if(esc){v+=x;esc=false;}else if(x=='\\')esc=true;else if(x=='"')break;else v+=x;}return v;}
std::string securityFailure(){return "LYCAN SECURITY\n\nPackage rejected.\n\nReason:\nSHA-256 verification failed.\n\nThe package was NOT installed.";}
std::string transactionFailure(const std::string&r){return "LYCAN PACKAGE MANAGER\n\nInstallation failed.\n\nReason:\n"+r+"\n\nThe previous version was restored.";}
std::string esc(std::string s){std::string r;for(char c:s){if(c=='\\'||c=='|'||c=='\n'||c=='\r')r+='\\';if(c=='\n')r+='n';else if(c=='\r')r+='r';else r+=c;}return r;}
std::string unesc(const std::string&s){std::string r;bool e=false;for(char c:s){if(e){r+=(c=='n'?'\n':c=='r'?'\r':c);e=false;}else if(c=='\\')e=true;else r+=c;}return r;}
std::vector<std::string> split(const std::string&line){std::vector<std::string>v;std::string x;bool e=false;for(char c:line){if(e){x+='\\';x+=c;e=false;}else if(c=='\\')e=true;else if(c=='|'){v.push_back(unesc(x));x.clear();}else x+=c;}v.push_back(unesc(x));return v;}
std::string timestamp(){return std::to_string(std::chrono::duration_cast<std::chrono::seconds>(std::chrono::system_clock::now().time_since_epoch()).count());}
std::string permissionsText(const Package&p){std::string s;for(size_t i=0;i<p.permissions.size();++i){if(i)s+=',';s+=p.permissions[i];}return s;}
}}
namespace lycan {
PackageManager::PackageManager(Lyfs&fs,SecurityPolicy&s):fs_(fs),security_(s),db_(fs_.hostPath("/system/packages.db")){}
bool PackageManager::validId(const std::string&id){if(id.empty()||id.size()>80)return false;for(unsigned char c:id)if(!(std::isalnum(c)||c=='-'||c=='_'||c=='.'))return false;return true;}
bool PackageManager::recordInstall(const Package&in,const std::string&checksum,const std::string&previousVersion){auto all=installed();Package p=in;p.installLocation="/apps/"+p.id;p.installTime=timestamp();p.sha256=checksum;p.previousVersion=previousVersion;bool replaced=false;for(auto&x:all)if(x.id==p.id){x=p;replaced=true;}if(!replaced)all.push_back(p);std::filesystem::create_directories(db_.parent_path());std::ofstream out(db_,std::ios::trunc);if(!out)return false;out<<"LYCAN-PKGDB|1\n";for(const auto&x:all)out<<esc(x.id)<<'|'<<esc(x.name)<<'|'<<esc(x.version)<<'|'<<esc(x.publisher)<<'|'<<esc(x.installLocation)<<'|'<<esc(x.installTime)<<'|'<<esc(x.sha256)<<'|'<<esc(x.previousVersion)<<'|'<<esc(x.entry)<<'|'<<esc(permissionsText(x))<<'\n';return !out.fail();}
bool PackageManager::install(const Package&p){if(!validId(p.id)||p.publisher.empty()||!security_.publisherTrusted(p.publisher))return false;auto target=fs_.hostPath("/apps/"+p.id),cache=fs_.hostPath("/package-cache");std::error_code ec;std::filesystem::create_directories(cache,ec);if(ec)return false;std::string previous;for(const auto&x:installed())if(x.id==p.id)previous=x.version;auto token=std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()),stage=cache/(p.id+"."+token+".tmp"),backup=cache/(p.id+"."+token+".backup");std::filesystem::create_directories(stage,ec);if(ec)return false;std::string m="{\n  \"id\": \""+p.id+"\",\n  \"name\": \""+p.name+"\",\n  \"version\": \""+p.version+"\",\n  \"publisher\": \""+p.publisher+"\",\n  \"entry\": \""+p.entry+"\"\n}\n";if(!fs_.writeText("/package-cache/"+stage.filename().string()+"/manifest.json",m)){std::filesystem::remove_all(stage,ec);return false;}bool had=std::filesystem::exists(target);if(had){std::filesystem::rename(target,backup,ec);if(ec){std::filesystem::remove_all(stage,ec);return false;}}std::filesystem::rename(stage,target,ec);if(ec){if(had)std::filesystem::rename(backup,target,ec);return false;}if(!recordInstall(p,p.sha256,previous)){std::filesystem::remove_all(target,ec);if(had)std::filesystem::rename(backup,target,ec);return false;}std::filesystem::remove_all(backup,ec);return true;}
bool PackageManager::inspectArchive(const std::filesystem::path&path,Package&pkg,std::string*error)const{PackageManifest m;std::vector<PackageEntry>entries;std::string e;if(!PackageArchive::inspect(path,m,entries,e)){if(error)*error=e;return false;}pkg.id=m.id;pkg.name=m.name;pkg.version=m.version;pkg.publisher=m.publisher;pkg.entry=m.entry;pkg.permissions=m.permissions;pkg.source=path;if(!validId(pkg.id)){if(error)*error="invalid package id";return false;}if(pkg.entry.rfind("/apps/"+pkg.id+"/",0)!=0){if(error)*error="manifest entry must stay inside its app";return false;}return true;}
std::string PackageManager::packageSha256(const std::filesystem::path&p){return PackageArchive::sha256File(p);} bool PackageManager::verifySha256(const std::string&a,const std::string&e){return isSha256(a)&&isSha256(e)&&lower(a)==lower(e);} std::string PackageManager::catalogSha256(const std::string&j,const std::string&id,const std::string&version){size_t p=0;while((p=j.find('{',p))!=std::string::npos){auto e=j.find('}',p+1);if(e==std::string::npos)break;auto o=j.substr(p,e-p+1);if(field(o,"id")==id&&field(o,"version")==version){auto d=field(o,"sha256");return isSha256(d)?lower(d):std::string{};}p=e+1;}return{};}
bool PackageManager::installArchiveFromCatalog(const std::filesystem::path&p,const std::string&j,std::string*error){Package x;std::string e;if(!inspectArchive(p,x,&e)){if(error)*error=e;return false;}auto expected=catalogSha256(j,x.id,x.version);if(!isSha256(expected)){if(error)*error=securityFailure();return false;}return installArchive(p,expected,error);}
bool PackageManager::installArchive(const std::filesystem::path&path,const std::string&expected,std::string*error){if(!isSha256(expected)||!verifySha256(packageSha256(path),expected)){if(error)*error=securityFailure();return false;}Package p;std::string e;if(!inspectArchive(path,p,&e)){if(error)*error=e;return false;}if(!security_.publisherTrusted(p.publisher)){if(error)*error="publisher is not trusted";return false;}std::string previous;for(const auto&x:installed())if(x.id==p.id)previous=x.version;auto cache=fs_.hostPath("/package-cache"),target=fs_.hostPath("/apps/"+p.id);std::error_code ec;std::filesystem::create_directories(cache,ec);if(ec){if(error)*error=transactionFailure(ec.message());return false;}auto token=std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()),stage=cache/(p.id+"."+token+".tmp"),backup=cache/(p.id+"."+token+".backup"),dbBackup=cache/(p.id+"."+token+".dbbackup");std::filesystem::create_directories(stage,ec);if(ec){if(error)*error=transactionFailure(ec.message());return false;}bool had=std::filesystem::exists(target),hadDb=std::filesystem::exists(db_);if(hadDb){std::filesystem::copy_file(db_,dbBackup,std::filesystem::copy_options::overwrite_existing,ec);if(ec){std::filesystem::remove_all(stage,ec);if(error)*error=transactionFailure("cannot protect package database: "+ec.message());return false;}}auto rollback=[&]{std::error_code x;if(std::filesystem::exists(target))std::filesystem::remove_all(target,x);if(had&&std::filesystem::exists(backup))std::filesystem::rename(backup,target,x);std::filesystem::remove_all(stage,x);if(hadDb&&std::filesystem::exists(dbBackup))std::filesystem::copy_file(dbBackup,db_,std::filesystem::copy_options::overwrite_existing,x);else if(!hadDb)std::filesystem::remove(db_,x);std::filesystem::remove(dbBackup,x);};PackageManifest sm;std::vector<PackageEntry>se;if(!PackageArchive::extract(path,stage,sm,e)){rollback();if(error)*error=transactionFailure(e);return false;}if(sm.id!=p.id||sm.version!=p.version||sm.publisher!=p.publisher||!validId(sm.id)||sm.entry.rfind("/apps/"+p.id+"/",0)!=0||!security_.publisherTrusted(sm.publisher)){rollback();if(error)*error=transactionFailure("staged manifest validation failed");return false;}auto rel=sm.entry.substr(std::string("/apps/").size()+p.id.size()+1);if(rel.empty()||rel.find("..")!=std::string::npos||!std::filesystem::exists(stage/rel)){rollback();if(error)*error=transactionFailure("staged entry point is missing or unsafe");return false;}if(had){std::filesystem::rename(target,backup,ec);if(ec){rollback();if(error)*error=transactionFailure("cannot stage previous version: "+ec.message());return false;}}std::filesystem::rename(stage,target,ec);if(ec){rollback();if(error)*error=transactionFailure("cannot commit staged application: "+ec.message());return false;}p.sha256=expected;if(!recordInstall(p,expected,previous)){rollback();if(error)*error=transactionFailure("cannot update installed-package database");return false;}std::filesystem::remove_all(backup,ec);std::filesystem::remove(dbBackup,ec);if(ec&&error)*error="LYCAN PACKAGE MANAGER\n\nInstallation completed with recoverable temporary files retained.\n\nReason:\n"+ec.message();return true;}
bool PackageManager::uninstall(const std::string&id){if(!validId(id)||!fs_.remove("/apps/"+id))return false;auto all=installed();std::ofstream out(db_,std::ios::trunc);if(!out)return false;out<<"LYCAN-PKGDB|1\n";for(const auto&p:all)if(p.id!=id)out<<esc(p.id)<<'|'<<esc(p.name)<<'|'<<esc(p.version)<<'|'<<esc(p.publisher)<<'|'<<esc(p.installLocation)<<'|'<<esc(p.installTime)<<'|'<<esc(p.sha256)<<'|'<<esc(p.previousVersion)<<'|'<<esc(p.entry)<<'|'<<esc(permissionsText(p))<<'\n';return !out.fail();}
bool PackageManager::rollback(const std::string&id){return validId(id)&&fs_.ready();}
std::vector<Package> PackageManager::installed()const{std::vector<Package>v;std::ifstream in(db_);if(!in)return v;std::string line;std::getline(in,line);while(std::getline(in,line)){if(line.empty())continue;auto f=split(line);if(f.size()<10)continue;Package p;p.id=f[0];p.name=f[1];p.version=f[2];p.publisher=f[3];p.installLocation=f[4];p.installTime=f[5];p.sha256=f[6];p.previousVersion=f[7];p.entry=f[8];std::stringstream ss(f[9]);std::string x;while(std::getline(ss,x,','))if(!x.empty())p.permissions.push_back(x);if(validId(p.id)&&!p.installLocation.empty())v.push_back(p);}return v;}
}